#include <stdlib.h>
#include <string.h>

typedef struct {
    int m, k;
    int *stream;      // circular buffer for last m elements
    int start;        // start index in circular buffer
    int size;         // current size (<= m)
    int count;        // total elements added

    int *freq;        // frequency array for numbers 1..100000
    long long totalSum; // sum of all elements in window
} MKAverage;

MKAverage* mKAverageCreate(int m, int k) {
    MKAverage *obj = (MKAverage*)malloc(sizeof(MKAverage));
    obj->m = m;
    obj->k = k;
    obj->stream = (int*)malloc(sizeof(int)*m);
    obj->start = 0;
    obj->size = 0;
    obj->count = 0;
    obj->freq = (int*)calloc(100001, sizeof(int));
    obj->totalSum = 0;
    return obj;
}

void mKAverageAddElement(MKAverage* obj, int num) {
    if (obj->size < obj->m) {
        // add new element
        obj->stream[(obj->start + obj->size) % obj->m] = num;
        obj->freq[num]++;
        obj->totalSum += num;
        obj->size++;
    } else {
        // remove oldest element
        int old = obj->stream[obj->start];
        obj->freq[old]--;
        obj->totalSum -= old;
        // add new element
        obj->stream[obj->start] = num;
        obj->freq[num]++;
        obj->totalSum += num;
        obj->start = (obj->start + 1) % obj->m;
    }
    obj->count++;
}

int mKAverageCalculateMKAverage(MKAverage* obj) {
    if (obj->size < obj->m) return -1;

    int m = obj->m, k = obj->k;
    int toRemove = k;

    // Remove k smallest elements sum
    long long sumSmall = 0;
    int rem = toRemove;
    for (int val = 1; val <= 100000 && rem > 0; val++) {
        if (obj->freq[val] > 0) {
            int take = obj->freq[val] < rem ? obj->freq[val] : rem;
            sumSmall += (long long)val * take;
            rem -= take;
        }
    }

    // Remove k largest elements sum
    long long sumLarge = 0;
    rem = toRemove;
    for (int val = 100000; val >= 1 && rem > 0; val--) {
        if (obj->freq[val] > 0) {
            int take = obj->freq[val] < rem ? obj->freq[val] : rem;
            sumLarge += (long long)val * take;
            rem -= take;
        }
    }

    long long sumMid = obj->totalSum - sumSmall - sumLarge;
    int countMid = m - 2*k;
    return (int)(sumMid / countMid);
}

void mKAverageFree(MKAverage* obj) {
    if (!obj) return;
    free(obj->stream);
    free(obj->freq);
    free(obj);
}

